 p_id=>wwv_flow_api.id(20145347090086435)
,p_lov_name=>'FIELD_LOCATION'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT    CASE',
'              WHEN TERR_ID IS NULL THEN NULL',
'              ELSE TERRITORY || '' - '' || TERR_ID',
'          END',
'       || '' ''',
'       || CASE WHEN ARR_ID IS NULL THEN NULL ELSE AREA || '' - '' || ARR_ID END',
'       || '' ''',
'       || CASE',
'              WHEN ZONE_ID IS NULL THEN NULL',
'              ELSE ZONES || '' - '' || ZONE_ID',
'          END',
'       || '' ''',
'       || CASE',
'              WHEN REG_ID IS NULL THEN NULL',
'              ELSE REGION || '' - '' || REG_ID',
'          END    AS DD,',
'       ID        AS r',
'  FROM FIELD_STRUCTURE',
' WHERE typ NOT IN (''DEPO'', ''LOC'');'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'R'
,p_display_column_name=>'DD'
,p_group_sort_direction=>'ASC'
,p_default_sort_column_name=>'DD'
,p_default_sort_direction=>'ASC'
);
