'        ''},'';',
'      end loop;',
'    else',
'      for i in 1 .. l_loop_count loop',
'        l_json := l_json || ''{'' ||',
'          apex_javascript.add_attribute(''R'', l_lov(gco_lov_return_col)(i), false, true) ||',
'          apex_javascript.add_attribute(''D'', l_lov(gco_lov_display_col)(i), false, false) ||',
'        ''},'';',
