'DECLARE',
'    l_user_id NUMBER;',
'BEGIN',
'    -- Get the currently logged-in user ID',
'    l_user_id := :user_id;',
'',
'    IF :P9_ID IS NOT NULL THEN',
'        -- Update',
'        UPDATE DEPARTMENTS',
'        SET upd_by = l_user_id,',
