'SELECT x."ID",',
'         NULL',
'             link_class,',
'         apex_page.get_url (p_items => ''P14_ID'', p_values => x."ID")',
'             link,',
'         NULL',
'             icon_class,',
'         NULL',
'             link_attr,',
'         NULL',
'             icon_color_class,',
'         CASE WHEN NVL ( :P14_ID, ''0'') = x."ID" THEN ''is-active'' ELSE '' '' END',
'             list_class,',
'            SUBSTR ("EMP_ID", 1, 50)',
'         || (CASE WHEN LENGTH ("EMP_ID") > 50 THEN ''...'' END)',
'             list_title,',
'            SUBSTR ("F_NAME" || '' '' || "L_NAME" || '' Department : ''  || dp.DEPT_NAME, 1, 50)',
'         || (CASE WHEN LENGTH ("F_NAME" || '' '' || "L_NAME") > 50 THEN ''...'' END)',
'             list_text,',
'         NULL',
'             list_badge',
'    FROM EMPLOYEES x, departments dp',
'   WHERE     x.DEPT_ID = dp.id(+)',
'         AND x.com_id = :g_com_id',
'         AND (   :P14_SEARCH IS NULL',
'              OR UPPER (x."EMP_ID") LIKE ''%'' || UPPER ( :P14_SEARCH) || ''%''',
'              OR UPPER ((x."F_NAME" || '' '' || x."L_NAME" || '' Department : '' || dp.DEPT_NAME)) LIKE',
'                     ''%'' || UPPER ( :P14_SEARCH) || ''%'')',
'ORDER BY "EMP_ID"'))
