'    l_query    VARCHAR2 (4000);',
'    v_status   NUMBER;',
'BEGIN',
'    v_status := :P14_ST;',
'',
'    IF v_status = 1',
'    THEN',
'        l_query := ''select etype d, id r from t_emp_typ'';',
'    elsif  v_status = 2 ',
'      then',
'        l_query := ''select etype d, id r from t_sep_typ'';',
'    else ',
'         l_query := ''select etype d, id r from t_emp_typ'';',
'    END IF;',
'',
'    RETURN l_query;',
'END;'))
