'               SET NAME = :P15_FATHER, UPD_BY = :user_id, UPD_DATE = SYSDATE',
'             WHERE EMP_ID = :P15_ID AND RELATION = 1;',
'',
'            -- If no record updated, insert new',
'            IF SQL%ROWCOUNT = 0',
'            THEN',
'                INSERT INTO EMP_FAMILY_DTL (EMP_ID,',
