'    l_user_id := :user_id;',
'',
'    IF :P16_ID IS NOT NULL THEN',
'        -- Update',
'        UPDATE EMP_EXPERIENCE',
'        SET upd_by = l_user_id,',
'            upd_date = sysdate',
