,p_process_name=>'Update Log'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_user_id NUMBER;',
'BEGIN',
'    -- Get the currently logged-in user ID',
'    l_user_id := :user_id;',
'',
'    IF :P17_ID IS NOT NULL THEN',
'        -- Update',
'        UPDATE EMP_TRAINING',
'        SET upd_by = l_user_id,',
'            upd_date = sysdate',
'        WHERE id = :P17_ID;',
'    END IF;',
' exception ',
'    when others then ',
'    null;',
'END;',
''))
