'    l_query    VARCHAR2 (4000);',
'    v_typ      VARCHAR2 (100);',
'    v_exam_id  NUMBER := :P18_EXAM;',
'BEGIN',
'    BEGIN',
'        SELECT typ INTO v_typ FROM exams ex',
'        WHERE ex.id = v_exam_id;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            v_typ := NULL;  -- or some default value',
'    END;',
'',
'    IF  v_typ = ''SECONDARY'' THEN',
'        l_query := ''SELECT NAME DIS, ID RET FROM SUBJECTS WHERE TYP = ''''GRP'''''';',
'    ELSE',
'        l_query := ''SELECT NAME DIS, ID RET FROM SUBJECTS WHERE TYP = ''''SUB'''''';',
'    END IF;',
'',
'    RETURN l_query;',
'END;',
''))
