,p_display_point=>'REGION_POSITION_02'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/24/2024 8:33:07 AM (QP5 v5.362) */',
'  SELECT x."ID",',
'         NULL',
'             link_class,',
'         apex_page.get_url (p_items => ''P21_ID'', p_values => x."ID")',
'             link,',
'         NULL',
'             icon_class,',
'         NULL',
'             link_attr,',
'         NULL',
'             icon_color_class,',
'         CASE WHEN NVL ( :P21_ID, ''0'') = x."ID" THEN ''is-active'' ELSE '' '' END',
'             list_class,',
'            SUBSTR (x."NAME" || '', '' || y."NAME", 1, 50)',
'         || (CASE WHEN LENGTH (x."NAME") > 50 THEN ''...'' END)',
'             list_title,',
'            SUBSTR (x."BN_NAME" || '', '' || y."BN_NAME", 1, 50)',
'         || (CASE WHEN LENGTH (x."BN_NAME") > 50 THEN ''...'' END)',
'             list_text,',
'         NULL',
'             list_badge',
'    FROM "UPAZILA" x, "DISTRICT" y',
'   WHERE     y.ID = x.DISTRICT_ID',
'         AND (   :P21_SEARCH IS NULL',
'              OR UPPER (x."NAME") LIKE ''%'' || UPPER ( :P21_SEARCH) || ''%''',
'              OR UPPER (y."NAME") LIKE ''%'' || UPPER ( :P21_SEARCH) || ''%''',
'              OR UPPER (y."BN_NAME") LIKE ''%'' || UPPER ( :P21_SEARCH) || ''%''',
'              OR UPPER (x."BN_NAME") LIKE ''%'' || UPPER ( :P21_SEARCH) || ''%'')',
'ORDER BY y."NAME"'))
,p_ajax_enabled=>'Y'
