 p_id=>38
,p_user_interface_id=>wwv_flow_api.id(5230568823024378)
,p_name=>'Field Structure'
,p_alias=>'TREE-PAGE'
,p_step_title=>'Field Structure'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>'fMoveResize();'
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_last_updated_by=>'SADIQ'
,p_last_upd_yyyymmddhh24miss=>'20251127104313'
);
wwv_flow_api.create_page_plug(
 p_id=>wwv_flow_api.id(20001397034113139)
,p_plug_name=>'Field Structure'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>wwv_flow_api.id(5133259516024345)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select case when connect_by_isleaf = 1 then 0',
'            when level = 1             then 1',
'            else                           -1',
'       end as status, ',
'       level, ',
'       PARENT_NAME as title, ',
'       null as icon, ',
'       str_NAME as value, ',
'       str_id as tooltip, ',
'       case when TYP = ''Region'' then ',
'               apex_util.prepare_url(''f?p=''||:app_id||'':39:''||:app_session||'':T:::P38_SELECTED_NODE,P39_ID:''||id||'',''||id)',
'            when TYP = ''Zone'' then',
'               apex_util.prepare_url(''f?p=''||:app_id||'':39:''||:app_session||'':T:::P38_SELECTED_NODE,P39_ID:''||id||'',''||id)',
'            when TYP = ''Area'' then ',
'                apex_util.prepare_url(''f?p=''||:app_id||'':39:''||:app_session||'':T:::P38_SELECTED_NODE,P39_ID:''||id||'',''||id)',
'            when TYP = ''Territory'' then ',
'                apex_util.prepare_url(''f?p=''||:app_id||'':39:''||:app_session||'':T:::P38_SELECTED_NODE,P39_ID:''||id||'',''||id)',
'       end as link      ',
'       ',
'from FIELD_STRUCTURE',
'start with PARENT_ID = ''0''',
'connect by prior   str_id = PARENT_ID',
