wwv_flow_api.create_page_plug(
 p_id=>wwv_flow_api.id(20361218116433319)
,p_plug_name=>'employee details'
,p_region_name=>'htmlRepprint'
,p_component_template_options=>'#DEFAULT#'
,p_plug_display_sequence=>20
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'htp.p('' ',
'  <div  id = "divToPrint">',
'   <style>',
'    body {',
'      font-family: Arial, sans-serif;',
'      padding: 20px;',
'    }',
'    table {',
'      border-collapse: collapse;',
'      width: 100%;',
'      margin-bottom: 20px;',
'    }',
'    td, th {',
'      border: 1px solid #000;',
'      padding: 6px;',
'      text-align: left;',
'    }',
'    th {',
'      background-color: #f2f2f2;',
'    }',
'    h2 {',
'      margin-top: 40px;',
'    }',
'  </style>',
'',
'  <div class="header" style="display: flex; align-items: center; justify-content: center; text-align: center;">',
'    <img src="http://10.30.25.8:9001/ords/hrm/r/103/files/static/v77/ipi.png" alt="ibnsina" style="height: 80px; margin-right: 20px;">',
'    <div>',
'        <h1 style="margin: 0;">The IBN SINA Pharmaceutical Industry PLC</h1>',
'        <h2 style="margin: 0;">Employee Information Details</h2>',
'    </div>',
'</div>',
'',
'  ',
' <br>'');',
'',
'for emp in (',
' SELECT es.id,',
'       es.emp_id,',
'       es.f_name || '' '' || es.l_name    fname,',
'       to_char(es.dob, ''DD-MON-YYYY'') dob,',
'        to_char(es.RETIREMENT_DATE, ''DD-MON-YYYY'') RETIREMENT_DATE,',
'       es.mobile,',
'       dp.DEPT_NAME,',
'       dg.DESIGNATION,',
'       es.email,',
'       es.father,',
'       es.mother,',
'       es.gender,',
'       CASE',
'           WHEN RELIGION = ''I'' THEN ''Islam''',
'           WHEN RELIGION = ''H'' THEN ''Hindu''',
'           WHEN RELIGION = ''C'' THEN ''Christian''',
'           WHEN RELIGION = ''B'' THEN ''Buddho''',
'           else ''Others''',
'       END    AS RELIGION,',
'       es.height,',
'       es.weight,',
'       es.blood,',
'       es.nid,',
'          ''Area/Village: ''',
'       || es.address',
'       || '', Post Office: ''',
'       || NVL (un.name, ''N/A'')',
'       || '', Thana/Upazila: ''',
'       || NVL (upz.name, ''N/A'')',
'       || '', District: ''',
'       || NVL (dis.name, ''N/A'')',
'       || '', Division: ''',
'       || NVL (div.name, ''N/A'')         AS address,',
'       es.c_post,',
'       es.c_thana,',
'       es.c_district,',
'       es.c_division,',
'          ''Area/Village: ''',
'       || es.p_address',
'       || '', Post Office: ''',
'       || NVL (un1.name, ''N/A'')',
'       || '', Thana/Upazila: ''',
'       || NVL (upz1.name, ''N/A'')',
'       || '', District: ''',
'       || NVL (dis1.name, ''N/A'')',
'       || '', Division: ''',
'       || NVL (div1.name, ''N/A'')        AS p_address,',
'       div1.name birthplace,',
'       es.p_post,',
'       es.p_thana,',
'       es.p_district,',
'       es.p_division,',
'      -- DBMS_LOB.getlength (es.photo)    photo,',
'       to_char(es.join_date, ''DD-MON-YYYY'') join_date,',
'       CASE',
'           WHEN marital_status = ''M'' THEN ''Married''',
'           WHEN marital_status = ''U'' THEN ''Un Married''',
'           WHEN marital_status = ''D'' THEN ''Divorced''',
'           WHEN marital_status = ''W'' THEN ''Widowed''',
'       END    AS marital_status,',
'       es.emp_type,',
'       es.dept_id,',
'       es.loc_id,',
'       es.branch_id,',
'       es.desig_id,',
'       es.com_id,',
'       es.job_id,',
'       es.user_grp,',
'       es.passw,',
'       es.ent_by,',
'       es.ent_date,',
'       es.upd_by,',
'       es.upd_date,',
'       es.status',
'  FROM employees     es,',
'       division      div,',
'       district      dis,',
'       upazila       upz,',
'       unions        un,',
'       division      div1,',
'       district      dis1,',
'       upazila       upz1,',
'       unions        un1,',
'       departments   dp,',
'       designations  dg',
' WHERE     es.c_post = un.id(+)',
'       AND es.c_thana = upz.id(+)',
'       AND es.c_district = dis.id(+)',
'       AND es.c_division = div.id(+)',
'       AND es.p_post = un1.id(+)',
'       AND es.p_thana = upz1.id(+)',
'       AND es.p_district = dis1.id(+)',
'       AND es.p_division = div1.id(+)',
'       AND es.dept_id = dp.id(+)',
'       AND es.desig_id = dg.id(+)',
'       AND es.id = :P400_EMPID)',
'       loop',
'',
'',
'',
'',
'htp.p(''',
'  <table>',
'    <tr>',
'      <td><strong>Employee ID:</strong> ''||emp.emp_id||''</td>',
'      <td><strong>Name:</strong> ''||emp.fname||''</td>',
'      <td><strong>Join Date:</strong> ''||emp.join_date||''</td>    ',
'      <td><strong>Retirement Date:</strong> ''||emp.RETIREMENT_DATE||''</td>',
'    </tr>',
'    <tr>  ',
'      <td><strong>Designation :</strong> ''||emp.DESIGNATION||''</td>',
'      <td><strong>Department :</strong> ''||emp.DEPT_NAME||''</td>',
unistr('      <td><strong>Father\2019s Name:</strong> ''||emp.father||''</td>'),
unistr('      <td><strong>Mother\2019s Name:</strong> ''||emp.mother||''</td>'),
'    </tr>',
'    ',
'    <tr>',
'      <td colspan="2"><strong>Present Address:</strong> ''||emp.address||'' </td>',
'      <td colspan="2"><strong>Permanent Address:</strong> ''||emp.p_address||'' </td>',
'    </tr>',
'  </table>',
'',
'  <table>',
'    <tr>',
'      <td><strong>Date Of Birth:</strong> ''||emp.dob||''</td>',
'      <td><strong>Place Of Birth:</strong> ''||emp.birthplace||''</td>',
'      <td><strong>NID:</strong> ''||emp.nid||'' </td>',
'      <td><strong>Religion:</strong> ''||emp.RELIGION||'' </td>',
'    </tr>',
'    <tr>',
'',
'     ',
'      <td><strong>Height: </strong> ''||emp.height||''</td>',
'      <td><strong>Weight (kg):</strong> ''||emp.weight||''</td>',
'      <td><strong>Blood Group:</strong> ''||emp.blood||''</td>',
'      <td><strong>Email:</strong> ''||emp.email||'' </td>',
'    </tr>',
'    <tr>',
'      <td colspan="2"><strong>Personal Contact Number:</strong>''||emp.mobile||'' </td>',
'      <td colspan="2"><strong>Alternative Number:</strong>''||emp.mobile||''</td>',
'    </tr>',
'    <tr>',
'      <td><strong>Marital Status:</strong> ''||emp.marital_status||''</td>',
'      <td><strong>Marriage Date:</strong></td>',
'      <td><strong>Spouse Name:</strong></td>',
'      <td><strong>Occupation:</strong></td>',
'    </tr>',
'  </table>'');',
'end loop;',
'htp.p(''',
'  <h2>Educational Qualification</h2>',
'  <table>',
'    <tr>',
'      <th>Degrees</th>',
'      <th>Passing Year</th>',
'      <th>Institute</th>',
'      <th>University/Board</th>',
'      <th>Group/Subject</th>      ',
'      <th>Result/GPA</th>',
'    </tr>',
'    <tr>',
'      <td></td>',
'      <td></td>',
'      <td></td>',
'      <td></td>',
'      <td></td>',
'      <td></td>',
'    </tr>    ',
'  </table>',
'',
'  <h2>Training & Certification</h2>',
'  <table>',
'    <tr>',
'      <th>Training Title</th>',
'      <th>Topic Covered</th>',
'      <th>Institute</th>',
'      <th>From Date</th>',
