'    // Get the dynamic content container',
'    var content = document.getElementById(''divToPrint'');',
'    ',
'    // Open a new window for printing',
'    var printWindow = window.open('''', ''_blank'');',
'    ',
'    // Write dynamic content into the new window',
'    printWindow.document.write(''<html><head><title>Employee Details</title></head><body><div></div>'');',
'    printWindow.document.write(content.innerHTML);',
'    printWindow.document.write(''</body></html>'');',
'    ',
'    // Close the document',
'    printWindow.document.close();',
'    ',
'    // Print the content',
'    printWindow.print();',
'}',
'',
'',
'printContent();',
'window.close();'))
