wwv_flow_api.create_page_plug(
 p_id=>wwv_flow_api.id(41195858237453617)
,p_plug_name=>'employee details'
,p_region_name=>'htmlRepprint'
,p_component_template_options=>'#DEFAULT#'
,p_plug_display_sequence=>20
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  htp.p('' ',
'  <div  id = "divToPrint">',
'  <style>',
'    body{font-family:Arial,sans-serif;margin:40px}h1,h2{text-align:center}table{width:100%;border-collapse:collapse;margin-bottom:30px}table,th,td{border:1px solid #000}th,td{padding:8px;text-align:left;vertical-align:top}.section-title{background-co'
||'lor:#f2f2f2;font-weight:700;text-align:center}.section-title th{text-align:center}.footer-note{display:flex;justify-content:space-between;margin-top:50px;font-weight:700}.nobord{border:none}.nobord td{border:none}.sl{font-weight:700}@media print{body'
||'{font-size:10pt}table{width:100%;border-collapse:collapse;font-size:9pt}table th,table td{padding:2px 4px;border:1px solid #000}@page{size:A4;margin:10mm}*{margin:0;padding:0;box-sizing:border-box}img{max-width:100%;height:auto}.no-print{display:none'
||'}}',
'  </style>',
'  <div class="header" style="display: flex; align-items: center; justify-content: center; text-align: center;">',
'    <img src="http://10.30.25.8:9001/ords/hrm/r/103/files/static/v77/ipi.png" alt="ibnsina" style="height: 80px; margin-right: 20px;">',
'    <div>',
'        <h1 style="margin: 0;">'');',
'declare',
'  v_name varchar2(100);',
'BEGIN',
'  SELECT name INTO v_name ',
'   FROM company WHERE id = :G_COM_ID;',
'  htp.p(''<h1>''||v_name||''</h1>'' );',
'EXCEPTION',
'  WHEN NO_DATA_FOUND THEN',
'  null; -- htp.p(''<h1> The IBN SINA Pharmaceutical Industry PLC </h1>'');',
'END;',
'',
'',
'          htp.p(''<h2 style="margin: 0;"> <u> Employee Information Details </u> </h2>',
'    </div>',
'</div>',
'',
'  ',
' <br>'');',
'BEGIN',
'for emp in (SELECT  es.id,  es.emp_id,   es.f_name || '' '' || es.l_name fname, TO_CHAR (dob, ''DD-MON-YYYY'') dob, ',
'get_age (dob) AS age, TO_CHAR (ADD_MONTHS (dob, 60 * 12), ''DD-MON-YYYY''  ) AS retirement_date, dp.DEPT_NAME,',
'dg.DESIGNATION, es.mobile, es.resp, es.email, es.father, father_c father_cont, es.mother, mother_c mother_cont, es.gender, ',
'  CASE WHEN RELIGION = ''I'' THEN ''Islam'' WHEN RELIGION = ''H'' THEN ''Hindu'' WHEN RELIGION = ''C'' THEN ''Christian'' WHEN RELIGION = ''B'' THEN ''Buddho'' ELSE ''Others'' END AS RELIGION, ',
'  es.height, es.weight, es.blood, es.nid, ''Area/Village: '' || es.address || '', Post Office: '' || NVL (un.name, ''1'') || '', Thana/Upazila: '' || NVL (upz.name, ''1'') || '', District: '' || NVL (dis.name, ''1'') || '', Division: '' || NVL (div.name, ''1'') AS add'
||'ress, ',
'  es.c_post, es.c_thana, es.c_district, es.c_division, ',
'  ''Area/Village: '' || es.p_address || '', Post Office: '' || NVL (un1.name, ''1'') || '', Thana/Upazila: '' || NVL (upz1.name, ''1'') || '', District: '' || NVL (dis1.name, ''1'') || '', Division: '' || NVL (div1.name, ''1'') AS p_address, ',
'  div1.name birthplace, es.p_post, es.p_thana, es.p_district, es.p_division, -- DBMS_LOB.getlength (es.photo)    photo,',
'  TO_CHAR (es.join_date, ''DD-MON-YYYY'') join_date, ',
'  CASE WHEN marital_status = ''M'' THEN ''Married'' WHEN marital_status = ''U'' THEN ''Un Married'' WHEN marital_status = ''D'' THEN ''Divorced'' WHEN marital_status = ''W'' THEN ''Widowed'' END AS marital_status, ',
'  es.emp_type, es.dept_id, es.loc_id, es.branch_id, es.desig_id, es.com_id, es.job_id, es.user_grp, ',
'  es.passw, es.conf_date, es.ent_by, es.ent_date,es.upd_by, es.upd_date, es.status, ',
'  CASE WHEN NVL (es.BRANCH_ID, str_id) IS NOT NULL THEN (SELECT STR_NAME D FROM FIELD_STRUCTURE fs  WHERE typ IN (''DEPO'', ''LOC'') AND fs.id = es.BRANCH_ID',
'  ) WHEN NVL (es.str_id, es.BRANCH_ID) IS NOT NULL THEN ( SELECT ',
'      CASE WHEN TERR_ID IS NULL THEN NULL ELSE ''Territory : '' || TERRITORY || '', '' END || '' '' || CASE WHEN ARR_ID IS NULL THEN NULL ELSE ''Area : '' || AREA || '', '' END || '' '' || CASE WHEN ZONE_ID IS NULL THEN NULL ELSE ''Zone : '' || ZONES || '', '' END |'
||'| '' '' || CASE WHEN REG_ID IS NULL THEN NULL ELSE ''Region : '' || REGION END || '' '' AS DD ',
'    FROM FIELD_STRUCTURE fs ',
'    WHERE fs.id = es.str_id AND typ NOT IN (''DEPO'', ''LOC'')',
'  ) END AS jobloc, ',
'    jg.GRADE_NAME grade, CASE WHEN es.status = 1 THEN ( SELECT ETYPE FROM T_EMP_TYP et ',
'    WHERE et.id = es.emp_type',
'  ) WHEN es.status = 2 THEN (SELECT ETYPE FROM T_SEP_TYP et WHERE et.id = es.emp_type',
'  ) END AS employment, ',
'  CASE WHEN es.status = 1 AND es.emp_type = 2 THEN TO_CHAR (conf_date, ''DD-MON-YYYY'') WHEN es.status = 2 THEN NULL END AS dateofcon, ',
'  spouse,   passport, CASE WHEN es.status = 1 THEN get_length (join_date, sysdate) WHEN es.status = 2 THEN get_length (join_date, sep_date) END AS total_length ',
'FROM employees es, division div, district dis, upazila upz, unions un, division div1,district dis1, upazila upz1, unions un1,departments dp, designations dg, JOB_GRADES jg ',
'WHERE es.c_post = un.id(+) AND es.c_thana = upz.id(+) AND es.c_district = dis.id(+) ',
'  AND es.c_division = div.id(+) AND es.p_post = un1.id(+) AND es.p_thana = upz1.id(+) ',
'  AND es.p_district = dis1.id(+) AND es.p_division = div1.id(+) AND es.dept_id = dp.id(+) ',
'  AND es.desig_id = dg.id(+) AND es.job_id = jg.id(+) AND es.id = : P401_EMPID',
')',
'       loop',
'htp.p(''<table class="nobord" >',
'     <tr><td class="sl">1</td><td class="sl">Staff ID  <span style="float:right"> : </span> </td><td>''||emp.emp_id||''</td></tr>',
'    <tr><td class="sl">2</td><td class="sl">Name <span style="float:right"> : </span> </td><td>''||emp.fname||''</td></tr>',
'    <tr><td class="sl">3</td><td class="sl">Designation <span style="float:right"> : </span></td><td>''||emp.DESIGNATION||''</td></tr>',
'    <tr><td class="sl">4</td><td class="sl">Role<span style="float:right"> : </span></td><td>''|| emp.resp ||''</td></tr>',
'    <tr><td class="sl">5</td><td class="sl">Department <span style="float:right"> : </span></td><td>''||emp.DEPT_NAME||''</td></tr>',
'    <tr><td class="sl">6</td><td class="sl">Employment Type <span style="float:right"> : </span></td><td>''|| emp.employment || '' </td></tr>',
'    <tr><td class="sl">7</td><td class="sl">Job Location <span style="float:right"> : </span></td><td>''|| emp.jobloc||''</td></tr>',
'    <tr><td class="sl">8</td><td class="sl">Date of Joining <span style="float:right"> : </span></td><td>''||emp.join_date||''</td></tr>',
'    <tr><td class="sl">9</td><td class="sl">Date of Confirmation <span style="float:right"> : </span> </td><td>''||emp.dateofcon||''</td></tr>',
'    <tr><td class="sl">10</td><td class="sl">Salary Grade & Scale <span style="float:right"> : </span></td> <td>''||emp.grade||'' </td></tr>',
'    <tr><td class="sl">11</td><td class="sl">Date of Birth & Age <span style="float:right"> : </span> </td><td>''||emp.dob|| '' and ''||emp.age|| ''</td></tr>',
'    <tr><td class="sl">12</td><td class="sl">Retirement Date <span style="float:right"> : </span> </td><td>''||emp.RETIREMENT_DATE||''</td></tr>',
'    <tr><td class="sl">13</td><td class="sl">Total Length of Service <span style="float:right"> : </span></td><td>''||emp.total_length||'' </td></tr>',
'    <tr><td class="sl">14</td><td class="sl">Service Length in Present Grade <span style="float:right"> : </span> </td><td>''||emp.total_length||'' </td></tr>',
'      </table>',
'<h3>15. Family & Others Information </h3>',
'    <table  class="nobord"> ',
'    <colgroup>',
'    <col style="width: 80px;"><col style="width: 80px;">',
'    <col style="width: 80px;"><col style="width: 80px;">',
'    <col style="width: 80px;"><col style="width: 80px;">',
'    <col style="width: 80px;"><col style="width: 80px;">',
'    <col style="width: 80px;"><col style="width: 80px;">',
'    <col style="width: 80px;"><col style="width: 80px;">',
'    </colgroup>',
'  <tr> <td colspan="5">Father''''s Name <span style="float:right"> : </span></td> <td colspan="5">''||emp.father||''</td> <td colspan="2">''||emp.father_cont||''</td> </tr>',
'  <tr> <td colspan="5">Mother''''s Name <span style="float:right"> : </span></td> <td colspan="5">''||emp.mother||''</td> <td colspan="2">''||emp.mother_cont||''</td> </tr>',
'  <tr> <td colspan="5">Religion <span style="float:right"> : </span></td> <td colspan="7">''||emp.RELIGION||''</td> </tr>',
'  <tr> <td colspan="5">NID <span style="float:right"> : </span></td> <td colspan="7">''||emp.nid||''</td> </tr>',
'  <tr> <td colspan="5">Passport No. <span style="float:right"> : </span></td> <td colspan="7">''||emp.passport||''</td> </tr>',
'  <tr> <td colspan="5">Email <span style="float:right"> : </span></td> <td colspan="7">''||emp.email||''</td> </tr>',
'  <tr> <td colspan="5">Contact Number <span style="float:right"> : </span></td> <td colspan="7">''||emp.mobile||''</td> </tr>',
'  <tr> <td colspan="5">Blood Group <span style="float:right"> : </span></td> <td colspan="7">''||emp.blood||''</td> </tr>',
'  <tr> <td colspan="5">Marital Status <span style="float:right"> : </span></td> <td colspan="7">''||emp.marital_status||''</td> </tr>',
'  <tr> <td colspan="5">Spouse Name <span style="float:right"> : </span></td> <td colspan="7">''||emp.spouse||''</td> </tr>',
'  <tr> <td colspan="5">Present Address <span style="float:right"> : </span></td> <td colspan="7">''||emp.address||''</td> </tr>',
'  <tr> <td colspan="5">Permanent Address <span style="float:right"> : </span></td> <td colspan="7">''||emp.p_address||''</td> </tr>',
'</table>',
'   '');',
'',
'end loop;',
'END;',
'',
' htp.p(''',
'</table>',
'  <h3>16. Emergency Contact </h3>',
'  <table class="centered-table" > <tr class="section-title">',
'      <th>Name Of Contact Person </th> <th> Relation </th> <th>Contact Number </th> <th>Alternative Contact</th> ',
'    </tr>',
'   '');',
'',
'DECLARE ',
' l_eg_found BOOLEAN := FALSE;',
' BEGIN',
' for ec in (SELECT ROW_NUMBER() OVER (ORDER BY NULL) AS slno,  (SELECT rname  FROM relations where id = relation) as relation , name, contact, remarks',
'  FROM emp_family_dtl WHERE emp_id = :P401_EMPID)',
' loop ',
' l_eg_found := true;',
' htp.p(''',
'    <tr> <td>''||ec.name||''</td> <td> ''||ec.relation||''</td> <td> ''||ec.contact||''</td> <td> ''||ec.remarks||''</td> </tr>  ',
'  '');',
'  end loop;',
'  IF NOT l_eg_found THEN',
'    htp.p(''',
'      <tr>',
'        <td colspan="3" style="text-align: center">Not Available </td>',
'      </tr>'');',
'  END IF;',
'  end;',
'',
'  htp.p(''',
'</table>',
'',
'',
'  <h3>17. Academic Qualification</h3>',
'  <table  >',
'    <tr class="section-title">',
'      <th>SLNO</th>',
'      <th>Degree</th> ',
'      <th>Subject/Group</th>',
'      <th>Institute</th>',
'      <th>Board/University</th> ',
'      <th>Result</th>     ',
'      <th>Passing Year</th>',
'    </tr>'');',
'    for ed in (SELECT ROW_NUMBER() OVER (ORDER BY NULL) AS slno,ee.emp_id,ee.exam,es.name examname,ee.sub_group, s.name subgrp,ee.passing_year,ee.duration, ',
'  ee.board,bu.name boardname,ee.cgpa results,ee.remarks,ee.empcode,ee.examgroup, ee.clas, ee.institute, ee.subject_name',
'FROM emp_education ee, exams es, board_university bu, subjects s',
'WHERE ee.exam=es.id(+) AND ee.board=bu.id(+) and ee.sub_group=s.id(+) and ee.emp_id = :P401_EMPID order by ee.passing_year desc)',
'loop',
'  htp.p('' <tr>',
'        <td style="text-align: center">''||ed.slno||''</td>',
'        <td>''||ed.examname||''</td>',
'        <td>''||ed.subgrp||''</td>',
'        <td>''||ed.INSTITUTE||''</td>        ',
'        <td>''||ed.boardname||''</td>        ',
'        <td>''||ed.results||''</td>  ',
'        <td style="text-align: center">''||ed.passing_year||''</td> ',
'    </tr>',
'  '');',
'end loop;',
'htp.p(''',
'</table>'');',
'',
'htp.p(''',
'  <h3>18. Professional Qualification</h3>',
'  <table >',
'    <tr class="section-title">',
'      <th style="text-align: center" >SLNO</th>',
'      <th>Degree</th> ',
'      <th>Subject/Group</th>',
'      <th>Institute</th>',
'      <th>Board/University</th> ',
'      <th>Result</th>     ',
'      <th>Passing Year</th>',
'    </tr>',
'   <tr>',
'    <td style="text-align: center">1</td>  <td>''||null||''</td>   <td>''||null||''</td>   <td>''||null||''</td> <td>''||null||''</td>  <td>''||null||''</td>  <td style="text-align: center">''||null||''</td> ',
'    </tr>',
'  '');',
' htp.p(''',
'</table>',
'  <h3>19. Training & Certification</h3>',
'  <table>',
'    <tr class="section-title">',
'     <th>SL No.</th> <th>Course Title</th> <th>Topic Covered </th> <th>Institute</th> <th>Country</th> <th>From Date</th> <th>To Date</th> <th>Duration</th> <th>Result</th>',
'    </tr>   '');',
'declare ',
'l_data_found BOOLEAN := FALSE;',
'begin',
'for tr in (SELECT ROW_NUMBER() OVER(ORDER BY NULL) AS slno,training_name,topics,country,institution, TO_CHAR (start_date, ''DD-MON-YYYY'') start_date, TO_CHAR (completion_date, ''DD-MON-YYYY'') completion_date,duration,result',
'  FROM EMP_TRAINING',
' WHERE emp_id = :P401_EMPID)',
' loop',
' l_data_found := TRUE;',
' htp.p(''',
'    <tr> <td style="text-align: center">''||tr.slno||''</td> <td>''||tr.training_name||'' </td> <td>''||tr.topics||'' </td> <td>''||tr.institution||''</td> <td>''||tr.country||''</td> <td>''||tr.start_date||''</td> <td>''||tr.completion_date||''</td> <td>''||tr.dur'
||'ation||''</td> <td>''||tr.result||''</td></tr>',
'    '');',
'    end loop;',
'    IF NOT l_data_found THEN',
'    htp.p(''',
'      <tr>',
'        <td colspan="9" style="text-align: center">No Data Available </td>',
'      </tr>'');',
'  END IF;',
'  end;',
'   htp.p(''</table>',
'',
'',
' <h3>20. Experience (Before Joining) </h3>',
'',
'  <table>',
'    <tr class="section-title"> <th>SL No.</th> <th>Organization</th><th>Designation</th> <th>Department</th> <th>From Date</th><th>To Date</th> <th>Duration</th> <th>Remarks</th>  </tr>',
'    '');',
'declare ',
'l_data_found BOOLEAN := FALSE;',
'begin',
'    for xp in (SELECT ROW_NUMBER() OVER (ORDER BY NULL) AS slno, COMPANY_NAME org,JOB_TITLE desig, JOB_DES, TO_CHAR (start_date, ''DD-MON-YYYY'') START_DATE,TO_CHAR (END_DATE, ''DD-MON-YYYY'') END_DATE, DURATION, REMARKS',
'  FROM EMP_EXPERIENCE',
' WHERE emp_id = :P401_EMPID)',
'    loop',
'     l_data_found := TRUE;',
'    htp.p(''',
'    <tr><td style="text-align: center">''||xp.slno||''</td> <td>''||xp.org||'' </td> <td> ''||xp.desig||''</td> <td>''||xp.JOB_DES||''</td> <td>''||xp.START_DATE||'' </td> <td>''||xp.END_DATE||'' </td> <td>''||xp.DURATION||'' </td> <td>''||xp.REMARKS||'' </td> </tr>',
'    '');',
'',
'    end loop;',
'    IF NOT l_data_found THEN',
'    htp.p(''',
'      <tr>',
'        <td colspan="8" style="text-align: center">No Data Available </td>',
'      </tr>'');',
'  END IF;',
'  end;',
'htp.p(''',
'  </table>',
'',
'  <h3>21. Posting/ Transfer History</h3>',
'  <table>',
'    <tr class="section-title">',
'    <th>SL No.</th> ',
'    <th>Designation </th>',
'    <th>Department</th>   ',
'    <th>Place of Posting</th>      ',
'    <th>Date</th>',
'    <th> Assignment / Responsibility</th>',
'    <th>Posting Type</th> ',
'    </tr>    ',
'    '');',
'declare ',
'l_data_found BOOLEAN := FALSE;',
'begin',
'    for tf in (select ROW_NUMBER() OVER (ORDER BY NULL) AS slno, emp_id, department,designation, floc,tloc,fdate,TO_CHAR (tdate, ''DD-MON-YYYY'') tdate,resp,typ',
'  from v_emp_thistory',
'  where emp_id = :P401_EMPID',
'  order by fdate )',
'    loop',
'     l_data_found := TRUE;',
'    htp.p('' <tr>',
'    <td style="text-align: center">''||tf.slno||''</td>',
'     <td>''||tf.designation||'' </td> ',
'     <td>''||tf.department||'' </td>      ',
'     <td>''||tf.tloc||'' </td>      ',
'      <td>''||tf.tdate||'' </td> ',
'      <td>''||tf.resp||'' </td> ',
'      <td>''||tf.typ||'' </td> ',
'      </tr>'');',
'',
'    end loop;',
'    IF NOT l_data_found THEN',
'    htp.p(''',
'      <tr>',
'        <td colspan="9" style="text-align: center">No Data Available </td>',
'      </tr>'');',
'  END IF;',
'  end;',
'htp.p(''',
'   ',
'  </table>',
'',
'',
'  <h3>22. Salary Review (Increment/Promotion/Conf./Sp. Ach./Sp. A/Per. A/Prof. A) History </h3>',
'  <table>',
'    <tr class="section-title"> <th>SL No.</th>  <th>Salary Grade </th><th>Review Date</th> <th>Review Type</th> <th>Effective Date</th> <th>Next review Date</th> <th>Amount</th> <th>Remarks</th> </tr>',
'    <tr> <td style="text-align: center">1</td> <td> </td> <td>''||null||''</td>  <td>''||null||''</td> <td>''||null||''</td> <td>''||null||''</td> <td>''||null||''</td> <td>''||null||''</td> </tr>',
'  </table>',
'',
'  <h3>23. Promotion History</h3>',
'  <table>',
'    <tr class="section-title"> <th>SL No.</th>  <th>Designation </th><th>Department</th> <th>Date</th> <th>Reference No.</th> <th>Type</th> <th>Remarks</th> </tr>',
'    <tr> <td style="text-align: center">1</td> <td> </td> <td>''||null||''</td>  <td>''||null||''</td> <td>''||null||''</td> <td>''||null||''</td> <td>''||null||''</td> </tr>',
'  </table>',
'',
'  <h3>24. Particulars of Reward</h3>',
'  <table>',
'    <tr class="section-title"> <th>SL No.</th> <th>Description</th><th>Authority</th><th>Date</th><th>Remarks</th></tr>',
'    <tr>  <td style="text-align: center">1</td>   <td>''||null||''</td> <td>''||null||''</td> <td>''||null||''</td> <td>''||null||''</td> </tr>',
'  </table>',
'',
'  <h3> 25. Particulars of Disciplinary Action</h3>',
'  <table>',
'    <tr class="section-title"><th>SL No.</th> <th>Description</th><th>Authority</th><th>Date</th><th>Remarks</th></tr>',
'    <tr> <td style="text-align: center">1</td>  <td>''||null||''</td> <td>''||null||''</td> <td>''||null||''</td> <td>''||null||''</td> </tr>',
'  </table>',
'',
'',
'  <h3>26. Nominee</h3>',
'  <table>',
'   <thead>',
'      <tr class="section-title">',
'        <th rowspan="2">SL No.</th> <th rowspan="2">Name &amp;<br>Contact No.</th> <th rowspan="2">Age</th><th rowspan="2">Relation</th>',
'         <th rowspan="2">NID</th><th rowspan="2">% of<br>Amount</th>',
'        <th colspan="4">Only Applicable (Column 7-10), if Nominee is Minor</th>',
'      </tr>',
'      <tr class="section-title">',
'        <th>  Guardian Name<br><span class="minor-note">(If Nominee is/are Minor)</span>',
'        </th>   <th>Relation with Minor</th><th>NID<br>(Guardian)</th><th>Contact No.<br>(Guardian)</th>',
'      </tr>',
'    </thead>',
'    <tbody>',
'    '');',
'declare ',
'l_data_found BOOLEAN := FALSE;',
'begin',
'for nm in (SELECT ROW_NUMBER() OVER (ORDER BY NULL) AS slno, EMP_ID, NNAME, CONT, REL, NID, TO_CHAR (DOB, ''DD-MON-YYYY'') DOB, AGE, PRC, MOBILE, m_gurdian, m_rel,  m_nid, m_contact, F_ADD ',
'FROM v_nom  ',
'WHERE emp_id = :P401_EMPID)',
'    loop',
'     l_data_found := TRUE;',
'    htp.p(''',
'      <tr> ',
'      <td style="text-align: center">''||nm.slno||''</td> <td> ''||nm.nname||''  '' ||nm.CONT||'' </td> <td> ''||nm.age||''</td>',
'      <td>''||nm.REL||''</td><td> ''||nm.nid||'' </td><td> ''||nm.PRC||'' </td><td>''||nm.m_gurdian||''</td>',
'      <td>''||nm.m_rel||''</td><td>''||nm.m_nid||''</td><td>''||nm.m_contact||''</td> ',
'      </tr>',
'    </tbody>'');',
' ',
' end loop;',
'    IF NOT l_data_found THEN',
'    htp.p(''',
'      <tr>',
'        <td colspan="10" style="text-align: center">No Data Available </td>',
'      </tr>'');',
'  END IF;',
'',
'end;',
'htp.p(''',
' </table>',
'',
' <h3>27. Guarantor</h3> ',
' '');  ',
'  declare ',
'  begin ',
'for gr in (SELECT ROW_NUMBER() OVER(ORDER BY NULL) AS slno,gname,gco,rel,prof,nid,mobile,preadd,peradd FROM v_guarator',
' WHERE emp_id = :P401_EMPID)',
' loop',
' htp.p(''',
'<table  class="nobord"> ',
'    <colgroup>',
'    <col style="width: 80px;"><col style="width: 80px;">',
'    <col style="width: 80px;"><col style="width: 80px;">',
'    <col style="width: 80px;"><col style="width: 80px;">',
'    <col style="width: 80px;"><col style="width: 80px;">',
'    <col style="width: 80px;"><col style="width: 80px;">',
'    <col style="width: 80px;"><col style="width: 80px;">',
'    </colgroup>',
'  <tr> <td colspan="12">''||gr.slno||'' ) </td> </tr>',
'  <tr> <td colspan="5">Full Name <span style="float:right"> : </span></td> <td colspan="7">''||gr.gname||''</td> </tr>',
unistr('  <tr> <td colspan="5">Father\2019s Name <span style="float:right"> : </span></td> <td colspan="7">''||gr.gco||''</td> </tr>  '),
'  <tr> <td colspan="5">Relation with Employee <span style="float:right"> : </span></td> <td colspan="7">''||gr.rel||''</td> </tr>',
'  <tr> <td colspan="5">Profession <span style="float:right"> : </span></td> <td colspan="7">''||gr.prof||''</td> </tr>  ',
'  <tr> <td colspan="5">Present Address <span style="float:right"> : </span></td> <td colspan="7">''||gr.preadd||''</td> </tr>',
'  <tr> <td colspan="5">Permanent Address <span style="float:right"> : </span></td> <td colspan="7">''||gr.peradd||''</td> </tr>',
'  <tr> <td colspan="5">NID <span style="float:right"> : </span></td> <td colspan="7">''||gr.nid||''</td> </tr>',
'  <tr> <td colspan="5">Contact Number <span style="float:right"> : </span></td> <td colspan="7">''||gr.mobile||''</td> </tr>',
'</table>'');',
'end loop;',
'end;',
'htp.p(''',
'  <div class="footer-note">',
'    <div>Prepared by</div>',
'    <div>Checked by</div>',
'  </div>',
'  </div> ''',
');',
''))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_translate_title=>'N'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
);
