 p_id=>wwv_flow_api.id(22979216824374717)
,p_plug_name=>'Attendance Status'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_api.id(5078876500024335)
,p_plug_display_sequence=>50
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'begin',
'htp.p(''',
'  <div  id = "divToPrint">',
'   <style>              ',
'        h2,h3{text-align:center}.employee-details{margin-bottom:5 px;padding:2px;background-color:#fff;}.employee-details{border:none;}',
'        .employee-details p{margin:2px 0;font-size:16px}table{width:100%;border-collapse:collapse;margin-top:5px}',
'        th,td{border:1px solid #ddd;padding:10px;border-collapse:collapse;text-align:left;font-size:11px}',
'        th{background-color: #dedede;color:#000; text-align:center} tr:nth-child(even){background-color:#f2f2f2}',
'        tr:hover{background-color:#ddd}',
'        .remarks{text-align:center;font-style:italic}',
'        .employee-details{padding:16px;border:1px solid #ddd;border-radius:6px;font-family:sans-serif}',
'        .row{display:flex; justify-content:space-between; margin-bottom:2px}.row p{flex:1;margin:0 8px 0 0}',
'        .employee-details {',
'    padding: 0;',
'    border: 0px solid #ddd;',
'    border-radius: 6px;',
'    font-family: sans-serif;',
'    text-align:center;',
'}',
'h1{',
'    border-bottom: 2px solid #000;',
'    margin: 10px;',
'    padding: 5px 10px;',
'}',
'',
'@media print {',
'body {',
'    font-size: 12px;',
'    ',
'  }',
'  table {',
'    width: 100%;',
'    border-collapse: collapse;',
'    font-size: 10px;',
'  }',
'  table th,',
'  table td {',
'    padding: 2px 4px;',
'    border: 1px solid #000;',
'  }',
'  @page {',
'    size: A4;',
'    margin: 10mm;',
'  }',
'  * {',
'    margin: 0;',
'    padding: 0;',
'    box-sizing: border-box;',
'  }',
'  img {',
'    max-width: 100%;',
'    height: auto;',
'  }',
'  .no-print {',
'    display: none;',
'  }',
'}',
'    </style>',
'',
''');',
'declare',
'  v_name varchar2(100);',
'BEGIN',
'  SELECT name INTO v_name ',
'   FROM company WHERE id = :G_COM_ID;',
'  htp.p(''<h1 style="text-align:center">''||v_name||''</h1>'' );',
'EXCEPTION',
'  WHEN NO_DATA_FOUND THEN',
'  null; -- htp.p(''<h1> The IBN SINA Pharmaceutical Industry PLC </h1>'');',
'END;',
'',
'',
'declare',
'    v_fdate   VARCHAR2 (100) := :P408_FROM_DATE; -- TO_CHAR ( to_date(:P408_FROM_DATE, ''DD-MON-RRRR''), ''DD-MON-RRRR'') ;',
'    v_tdate   VARCHAR2 (100) := :P408_TO_DATE; --TO_CHAR ( to_date(:P408_TO_DATE, ''DD-MON-RRRR''), ''DD-MON-RRRR'');',
'   BEGIN',
'   -- SELECT TO_CHAR ( :P408_FROM_DATE, ''DD-MON-RRRR'') fdt into v_fdate FROM DUAL',
'--where :P408_FROM_DATE = :P408_FROM_DATE;',
'   -- SELECT TO_CHAR ( :P408_TO_DATE, ''DD-MON-RRRR'') INTO v_tdate FROM DUAL;',
'htp.p('' <div class="employee-mst">',
' ',
'<div style="display: flex; justify-content: space-between; align-items: center;">',
'  <h2 style="margin: 0 auto; position: absolute; left: 50%; transform: translateX(-50%);">Employee Wise Attendance Detail</h2>',
'  <span style="margin-left: auto;">Print Time:  ''|| :print_time||''</span>',
'</div>',
'<br>',
'',
' <p style="text-align:center"> <span> Date : </span> ''||v_fdate||'' <span> to </span> ''||v_tdate||'' </p>'');',
'',
'EXCEPTION',
'  WHEN NO_DATA_FOUND THEN',
'  null;',
'END;',
'',
'',
'for e in (SELECT emp_id,',
'       ipi,',
'       fullname,',
'       department,',
'       designation',
'  FROM v_emp',
' WHERE emp_id = :P408_EMPLOYEE_ID)',
' loop     ',
'HTP.P(''',
'',
'    <div class="row">',
'        <p><strong>Employee ID :</strong> ''||e.ipi||''</p>',
'        <br>',
'        <p><strong>Employee Name :</strong> ''||e.fullname||''</p>',
'    </div>',
'      <br>',
'    <div class="row">',
'        <p><strong>Department :</strong> ''||e.department||''</p>',
'          <br>',
'        <p><strong>Designation :</strong> ''||e.designation||''</p>',
'    ',
'    ',
'    '');',
'',
'        end loop;',
'  HTP.P(''  </div>',
'</div>   ',
'<div class="employee-details">',
'    <table>',
'        <thead>',
'            <tr>',
'                <th>Date</th>',
'                <th>Day</th>',
'                <th>Status</th>',
'                <th>In Time</th>',
'                <th>Out Time</th>',
'                <th>Late In</th>',
'                <th>Early Out</th>',
'                <th>In Location</th>',
'                <th>Out Location</th>',
'                <th>Duty Hours</th>',
'                <th>Remarks</th>',
'            </tr>',
'        </thead>''',
'',
'        );',
'for xd in (SELECT aid,',
'       empid,',
'       attdate,',
'       weekd,attdt,',
'       office_start,',
'       office_end,',
'       shift_start,',
'       shift_end,',
'       status,',
'       in_time,',
'       out_time,',
'       punchout, punchin,',
'       late,',
'       early,',
'       in_id,',
'       inloc,',
'       out_id,',
'       outloc,',
'       total_h,',
'       notes,',
'       com_id,',
'       weekend,',
'       nextday,',
'       holiday',
'  FROM v_attrep',
' WHERE     empid = :P408_EMPLOYEE_ID',
'       AND attdate  BETWEEN TO_DATE(:P408_FROM_DATE, ''DD-Mon-YYYY'') AND   TO_DATE(:P408_TO_DATE, ''DD-Mon-YYYY'') ',
')',
'       loop',
'       htp.p(''',
'        <tbody>',
'            <tr>',
'                <td>''||xd.attdt||''</td>',
'                <td>''||xd.weekd||''</td>',
'                <td>''||xd.status||''</td>',
'                <td>''||xd.punchin||''</td>',
'                <td>''||xd.punchout||''</td>',
'                <td>''||xd.late||''</td>',
'                <td>''||xd.early||''</td>',
'                <td>''||xd.inloc||''</td>',
'                <td>''||xd.outloc||''</td>',
'                <td>''||xd.total_h||''</td>',
'                <td>''||xd.notes||''</td>',
'            </tr>'');',
'            end loop;',
'',
'        htp.p(''',
'    </tbody>',
' </table>',
'  </div>',
' </div>'');',
'',
'end;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
);
