wwv_flow_api.create_page_validation(
 p_id=>wwv_flow_api.id(24697720117108413)
,p_validation_name=>'prevent duplicate'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count INTEGER;',
'BEGIN',
'    -- Check if the same employee (EMPID) has already applied on the same date (M_INTIME or M_OUTTIME)',
'    SELECT COUNT(*)',
'    INTO v_count',
'    FROM MANUAL_ATT',
'    WHERE EMPID = :P411_EMPID',
'          AND (   TRUNC(M_INTIME) = TRUNC(TO_DATE(:P411_M_INTIME, ''DD-MON-YYYY HH:MIPM''))',
'                OR TRUNC(M_OUTTIME) = TRUNC(TO_DATE(:P411_M_OUTTIME, ''DD-MON-YYYY HH:MIPM''))',
'                OR (TRUNC(M_INTIME) = TRUNC(TO_DATE(:P411_M_OUTTIME, ''DD-MON-YYYY HH:MIPM''))',
'                    AND :P411_M_INTIME != :P411_M_OUTTIME)',
'                OR (TRUNC(M_OUTTIME) = TRUNC(TO_DATE(:P411_M_INTIME, ''DD-MON-YYYY HH:MIPM''))',
'                    AND :P411_M_OUTTIME != :P411_M_INTIME) )',
'          AND ( :P411_ID IS NULL OR :P411_ID != :P411_ID );',
'',
'    -- If a duplicate exists, raise an error and prevent form submission',
'    IF v_count > 0 THEN',
'        RETURN FALSE; -- Validation fails',
'    ELSE',
'        RETURN TRUE; -- Validation passes',
'    END IF;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Duplicate Application!!!!'
,p_always_execute=>'Y'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_api.create_page_validation(
 p_id=>wwv_flow_api.id(24698013290108416)
,p_validation_name=>'In time date out date must same'
,p_validation_sequence=>20
,p_validation=>'TRUNC(TO_DATE(:P411_M_INTIME, ''DD-MON-YYYY HH:MIPM'')) = TRUNC(TO_DATE(:P411_M_OUTTIME, ''DD-MON-YYYY HH:MIPM''))'
,p_validation2=>'PLSQL'
,p_validation_type=>'EXPRESSION'
,p_error_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Intime and Outtime must be same date!!',
'others date not alloed!!'))
,p_associated_item=>wwv_flow_api.id(25144299042699298)
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
