wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(24697327602108409)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update to next level'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_hod_id   NUMBER;',
'    v_md_id    NUMBER := 222000789;',
'    v_hr_id    NUMBER := 200007478;',
'BEGIN',
'  UPDATE MANUAL_ATT',
'           SET status = ''F''',
'   WHERE id = :P418_ID;',
'        UPDATE m_att_app_history',
'           SET APPROVAL_STATUS = :P418_APPROVAL_STATUS',
'         WHERE id = :P418_DID AND APPROVER_ID = :P418_APPROVER_ID;',
'    SELECT hod_id',
'      INTO v_hod_id',
'      FROM hod',
'     WHERE dept_id = (SELECT dept_id',
'                        FROM employees',
'                       WHERE id = :P418_EMPID);',
'    IF :P418_APPROVER_LEVEL = ''HOD''',
'    THEN  INSERT INTO m_att_app_history (m_att_id,',
'                                       approver_level,',
'                                       approver_id,',
'                                       approval_status,',
'                                       approval_date,',
'                                       comments,',
'                                       ent_date,',
'                                       ent_by)',
'             VALUES ( :P418_M_ATT_ID,',
'                     ''HR'',',
'                     v_hr_id,',
'                     ''PENDING'',',
'                     NULL,',
'                     ''Waiting for HR approval'',',
'                     SYSDATE,',
'                     NULL);',
'      UPDATE MANUAL_ATT',
'           SET status = ''F'', COMMENTS = ''Waiting for HR approval''',
'         WHERE id = :P418_ID;',
'         ',
'        UPDATE m_att_app_history',
'           SET APPROVAL_STATUS = :P418_APPROVAL_STATUS',
'         WHERE id = :P418_DID AND APPROVER_ID = :P418_APPROVER_ID;',
'',
'    ELSIF :P418_APPROVER_LEVEL = ''RP''   THEN     ',
'        INSERT INTO m_att_app_history (m_att_id,',
'                                       approver_level,',
'                                       approver_id,',
'                                       approval_status,',
'                                       approval_date,',
'                                       comments,',
'                                       ent_date,',
'                                       ent_by)',
'             VALUES ( :P418_M_ATT_ID,',
'                     ''HOD'',',
'                     v_hod_id,',
'                     ''PENDING'',',
'                     NULL,',
'                     ''Waiting for Head of Department (HOD) approval'',',
'                     SYSDATE,',
'                     NULL);',
'',
'        UPDATE MANUAL_ATT',
'           SET status = ''F'', COMMENTS = ''Waiting for Head of Department (HOD) approval''',
'         WHERE id = :P418_ID;',
'         ',
'        UPDATE m_att_app_history',
'           SET APPROVAL_STATUS = :P418_APPROVAL_STATUS',
'         WHERE id = :P418_DID AND APPROVER_ID = :P418_APPROVER_ID;',
'',
'   elsif :P418_APPROVER_LEVEL = ''HR'' then',
'          UPDATE MANUAL_ATT',
'           SET status = ''A'', COMMENTS = ''Finally Approved By HR Department''',
'           WHERE id = :P418_ID;',
'',
'          UPDATE m_att_app_history',
'           SET APPROVAL_STATUS = ''APPROVE''',
'        WHERE id = :P418_DID AND APPROVER_ID = :P418_APPROVER_ID;',
'',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(25671331043885815)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_region_id=>wwv_flow_api.id(25660426145885825)
,p_process_type=>'NATIVE_FORM_INIT'
,p_process_name=>'Initialize form Manual Attendance Approval '
);
end;
