wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(27156812610907444)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update to next level'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_hod_id   NUMBER;',
'    v_md_id    NUMBER := 222000789;',
'    v_hr_id    NUMBER := 200007478;',
'BEGIN',
'  UPDATE leave_request',
'           SET leave_status = ''F''',
'   WHERE leave_id = :P422_LEAVE_ID;',
'        UPDATE LEAVE_APP_HISTORY',
'           SET APPROVAL_STATUS = :P422_APPROVAL_STATUS',
'         WHERE id = :P422_DID AND APPROVER_ID = :P422_APPROVER_ID;',
'    SELECT hod_id',
'      INTO v_hod_id',
'      FROM hod',
'     WHERE dept_id = (SELECT dept_id',
'                        FROM employees',
'                       WHERE id = :P422_EMPID);',
'    IF :P422_APPROVER_LEVEL = ''HOD''',
'    THEN  INSERT INTO LEAVE_APP_HISTORY (LEAVE_ID,',
'                                       approver_level,',
'                                       approver_id,',
'                                       approval_status,',
'                                       approval_date,',
'                                       comments,',
'                                       ent_date,',
'                                       ent_by)',
'             VALUES ( :P422_LEAVE_ID,',
'                     ''HR'',',
'                     v_hr_id,',
'                     ''PENDING'',',
'                     NULL,',
'                     ''Waiting for HR approval'',',
'                     SYSDATE,',
'                     NULL);',
'      UPDATE leave_request',
'           SET leave_status = ''F'', COMMENTS = ''Waiting for HR approval''',
'         WHERE leave_id = :P422_LEAVE_ID;',
'         ',
'        UPDATE LEAVE_APP_HISTORY',
'           SET APPROVAL_STATUS = :P422_APPROVAL_STATUS',
'         WHERE id = :P422_DID AND APPROVER_ID = :P422_APPROVER_ID;',
'',
'    ELSIF :P422_APPROVER_LEVEL = ''RP''   THEN     ',
'        INSERT INTO LEAVE_APP_HISTORY (LEAVE_ID,',
'                                       approver_level,',
'                                       approver_id,',
'                                       approval_status,',
'                                       approval_date,',
'                                       comments,',
'                                       ent_date,',
'                                       ent_by)',
'             VALUES ( :P422_LEAVE_ID,',
'                     ''HOD'',',
'                     v_hod_id,',
'                     ''PENDING'',',
'                     NULL,',
'                     ''Waiting for Head of Department (HOD) approval'',',
'                     SYSDATE,',
'                     NULL);',
'',
'        UPDATE leave_request',
'           SET leave_status = ''F'', COMMENTS = ''Waiting for Head of Department (HOD) approval''',
'         WHERE leave_id = :P422_LEAVE_ID;',
'         ',
'        UPDATE LEAVE_APP_HISTORY',
'           SET APPROVAL_STATUS = :P422_APPROVAL_STATUS',
'         WHERE id = :P422_DID AND APPROVER_ID = :P422_APPROVER_ID;',
'',
'   elsif :P422_APPROVER_LEVEL = ''HR'' then',
'          UPDATE leave_request',
'           SET leave_status = ''A'', COMMENTS = ''Finally Approved By HR Department''',
'           WHERE leave_id = :P422_LEAVE_ID;',
'',
'          UPDATE LEAVE_APP_HISTORY',
'           SET APPROVAL_STATUS = ''APPROVE''',
'        WHERE id = :P422_DID AND APPROVER_ID = :P422_APPROVER_ID;',
'',
'    END IF;',
'    exception ',
'    when others then ',
'    null;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
