wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(27578133948850736)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update to next level'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_hod_id   NUMBER;',
'    v_md_id    NUMBER := 222000789;',
'    v_hr_id    NUMBER := 200007478;',
'BEGIN',
'  UPDATE tour_req',
'           SET tour_status = ''F''',
'   WHERE tour_id = :P426_TOUR_ID;',
'        UPDATE tour_APP_HISTORY',
'           SET APPROVAL_STATUS = :P426_APPROVAL_STATUS',
'         WHERE id = :P426_DID AND APPROVER_ID = :P426_APPROVER_ID;',
'    SELECT hod_id',
'      INTO v_hod_id',
'      FROM hod',
'     WHERE dept_id = (SELECT dept_id',
'                        FROM employees',
'                       WHERE id = :P426_EMPID);',
'    IF :P426_APPROVER_LEVEL = ''HOD''',
'    THEN  INSERT INTO tour_APP_HISTORY (tour_ID,',
'                                       approver_level,',
'                                       approver_id,',
'                                       approval_status,',
'                                       approval_date,',
'                                       comments,',
'                                       ent_date,',
'                                       ent_by)',
'             VALUES ( :P426_TOUR_ID,',
'                     ''HR'',',
'                     v_hr_id,',
'                     ''PENDING'',',
'                     NULL,',
'                     ''Waiting for HR approval'',',
'                     SYSDATE,',
'                     NULL);',
'      UPDATE tour_req',
'           SET tour_status = ''F'', COMMENTS = ''Waiting for HR approval''',
'         WHERE tour_id = :P426_TOUR_ID;',
'         ',
'        UPDATE tour_APP_HISTORY',
'           SET APPROVAL_STATUS = :P426_APPROVAL_STATUS',
'         WHERE id = :P426_DID AND APPROVER_ID = :P426_APPROVER_ID;',
'',
'    ELSIF :P426_APPROVER_LEVEL = ''RP''   THEN     ',
'        INSERT INTO tour_APP_HISTORY (tour_ID,',
'                                       approver_level,',
'                                       approver_id,',
'                                       approval_status,',
'                                       approval_date,',
'                                       comments,',
'                                       ent_date,',
'                                       ent_by)',
'             VALUES ( :P426_TOUR_ID,',
'                     ''HOD'',',
'                     v_hod_id,',
'                     ''PENDING'',',
'                     NULL,',
'                     ''Waiting for Head of Department (HOD) approval'',',
'                     SYSDATE,',
'                     NULL);',
'',
'        UPDATE tour_req',
'           SET tour_status = ''F'', COMMENTS = ''Waiting for Head of Department (HOD) approval''',
'         WHERE tour_id = :P426_TOUR_ID;',
'         ',
'        UPDATE tour_APP_HISTORY',
'           SET APPROVAL_STATUS = :P426_APPROVAL_STATUS',
'         WHERE id = :P426_DID AND APPROVER_ID = :P426_APPROVER_ID;',
'',
'   elsif :P426_APPROVER_LEVEL = ''HR'' then',
'          UPDATE tour_req',
'           SET tour_status = ''A'', COMMENTS = ''Finally Approved By HR Department''',
'           WHERE tour_id = :P426_TOUR_ID;',
'',
'          UPDATE tour_APP_HISTORY',
'           SET APPROVAL_STATUS = ''APPROVE''',
'        WHERE id = :P426_DID AND APPROVER_ID = :P426_APPROVER_ID;',
'',
'    END IF;',
'    exception ',
'    when others then ',
'    null;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(27577731263850736)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_region_id=>wwv_flow_api.id(80364980481644018)
,p_process_type=>'NATIVE_FORM_INIT'
,p_process_name=>'Initialize form Manual Attendance Approval '
);
end;
