,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_SET_VALUE'
,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P428_DURATION_HOURS'
,p_attribute_01=>'SQL_STATEMENT'
,p_attribute_03=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT (CASE ',
'           WHEN TO_DATE(:P428_END_TIME, ''HH:MIAM'') < TO_DATE(:P428_START_TIME, ''HH:MIAM'') ',
'           THEN TO_DATE(:P428_END_TIME, ''HH:MIAM'') + 1',
'           ELSE TO_DATE(:P428_END_TIME, ''HH:MIAM'') ',
'        END',
'       - TO_DATE(:P428_START_TIME, ''HH:MIAM'')) * 24 dthours',
'FROM dual',
''))
,p_attribute_07=>'P428_START_TIME,P428_END_TIME'
,p_attribute_08=>'N'
,p_attribute_09=>'N'
,p_wait_for_result=>'Y'
);
