wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(27168936651893020)
,p_event_id=>wwv_flow_api.id(27168808487893019)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P428_DURATION_HOURS'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// Get values from APEX page items',
'var startVal = $v("P428_START_TIME"); // Example: "10:00PM"',
'var endVal   = $v("P428_END_TIME");   // Example: "06:00AM"',
'',
'// Function to parse "HH:MIPM" (like "10:00PM") into a Date object',
'function parseTime12h(timeStr) {',
'    if (!timeStr) return null;',
'    var match = timeStr.match(/^(\d{1,2}):(\d{2})(AM|PM)$/i);',
'    if (!match) return null;',
'',
'    var hours = parseInt(match[1], 10);',
'    var minutes = parseInt(match[2], 10);',
'    var ampm = match[3].toUpperCase();',
'',
'    if (ampm === "PM" && hours !== 12) hours += 12;',
'    if (ampm === "AM" && hours === 12) hours = 0;',
'',
'    var d = new Date();',
'    d.setHours(hours, minutes, 0, 0);',
'    return d;',
'}',
'',
'var startTime = parseTime12h(startVal);',
'var endTime   = parseTime12h(endVal);',
'',
'if (startTime && endTime) {',
'    // Overnight shift adjustment',
'    if (endTime < startTime) {',
'        endTime.setDate(endTime.getDate() + 1);',
'    }',
'',
'    // Calculate difference in hours',
'    var diffHours = (endTime - startTime) / (1000 * 60 * 60);',
'',
'    // Set value into P428_DURATION_HOURS',
'    $s("P428_DURATION_HOURS", diffHours);',
'} else {',
'    // If input is invalid',
'    $s("P428_DURATION_HOURS", "");',
'}',
''))
);
