,p_bind_type=>'bind'
,p_bind_event_type=>'ready'
);
wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(28983615598421625)
,p_event_id=>wwv_flow_api.id(28983593953421624)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// let gridView = apex.region(''vGridmn'').widget().interactiveGrid("getViews", "grid");',
'// let columns = gridView.getColumns();',
'// //let dnameColumn = columns.filter(column => column.elementId == ''c_dname'')[0];   // filter by staticId',
'// let dnameColumn = columns.filter(column => column.property == ''DAY1'')[0];   // filter by column name ',
'// dnameColumn.heading = ''Sun 11'';',
'// gridView.refreshColumns();',
'// gridView.refresh();',
'',
'var vmn = $(''#P430_MONTH'').val();',
'// Function to update column names based on year and month',
'function updateColumnNames(yearMonth) {',
'    // Extract year and month from the input (e.g., 202508 -> year = 2025, month = 08)',
'    let year = parseInt(yearMonth.substring(0, 4));',
'    let month = parseInt(yearMonth.substring(4, 6)) - 1;  // Month is 0-based (0 = January, 11 = December)',
'    ',
'    // Create a Date object for the 1st day of the month',
'    let firstDayOfMonth = new Date(year, month, 1);',
'    ',
'    // Array for the day names of the week (Sunday to Saturday)',
'    let daysOfWeek = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];',
'    ',
'    // Get the first day of the week (0 = Sunday, 1 = Monday, ...)',
'    let firstDay = firstDayOfMonth.getDay();',
'    ',
'    // Get the total number of days in the current month',
'    let lastDayOfMonth = new Date(year, month + 1, 0);  // 0th day of the next month gives the last day',
'    let totalDaysInMonth = lastDayOfMonth.getDate();  // Number of days in the current month',
'    ',
'    // Get the Interactive Grid and its columns',
'    let gridView = apex.region(''vGridmn'').widget().interactiveGrid("getViews", "grid");',
'    let columns = gridView.getColumns();',
'    ',
'    // Loop through each day of the month (1 to totalDaysInMonth) and update column headers',
'    for (let i = 1; i <= totalDaysInMonth; i++) {',
'        // Format the column name (e.g., DAY1, DAY2, ..., DAY31)',
'        let dayColumnName = ''DAY'' + i;  // Format as DAY1, DAY2, ...',
'        ',
'        // Filter the column based on its name (DAY1, DAY2, ..., DAY31)',
'        let column = columns.filter(col => col.property == dayColumnName)[0];',
'        ',
'        if (column) {',
'            // Calculate the day of the week for the current day',
'            let dayOfWeek = daysOfWeek[(firstDay + i - 1) % 7];  // Modulo 7 to get the weekday',
'            ',
'            // Update the column header to be "DayOfWeek DayNumber" (e.g., "Sun 1", "Mon 2", ...)',
'            column.heading = `${dayOfWeek} ${i}`;',
'        }',
'    }',
'    ',
'    // Refresh the columns to reflect the changes',
'    gridView.refreshColumns();',
'    gridView.refresh();',
'}',
'',
'// Call the function with the year and month (e.g., ''202508'' for August 2025)',
'updateColumnNames(vmn);',
''))
);
