,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'EMP_DETAILS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    vdept   VARCHAR2 (100) := :P430_DEPARTMENT;',
'BEGIN',
'    APEX_JSON.open_object;',
'    APEX_JSON.open_array (''items'');',
'    -- Query the data from your table using the parameter',
'    FOR rec',
'        IN (select  id as empid, DEPT_ID deptid, com_id as comid',
'from employees',
'where DEPT_ID = vdept',
'AND COM_ID = :G_COM_ID',
'AND ID NOT IN (SELECT EMPID',
'from ROSTER_MN',
'where COM_ID = :G_COM_ID ',
'AND YEARMN = :P430_MONTH))',
'    LOOP',
'        APEX_JSON.open_object;',
'        APEX_JSON.write (''empid'', rec.empid);',
'        APEX_JSON.write (''deptid'', rec.deptid);',
'        APEX_JSON.write (''comid'', rec.comid);      ',
'        APEX_JSON.close_object;',
'    END LOOP;',
'',
'    APEX_JSON.close_array;',
'    APEX_JSON.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
