wwv_flow_api.create_page_plug(
 p_id=>wwv_flow_api.id(28985952121421648)
,p_plug_name=>'attendance status'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_api.id(5078876500024335)
,p_plug_display_sequence=>40
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'sys.htp.p(''<div  id = "divToPrint">',
'<style>@page{size:A4;margin:12mm}:root{--ink:#111;--muted:#444;--rule:#000;--border:#000}',
'html,body{height:100%}',
'body{font-family:"Segoe UI",Tahoma,Arial,sans-serif;color:var(--ink);margin:0;-webkit-print-color-adjust:exact;print-color-adjust:exact;line-height:1.25}.page{width:190mm;margin:0 auto;padding:0}.report-header{display:flex;align-items:center;justify-'
||'content:center;gap:2px;padding:10px 0;border-bottom:2px solid var(--border);margin-bottom:10px}.logo{width:64px;height:64px}.title{text-align:center}.title h1{font-size:22px;margin:2px;font-weight:700}.title.subtitle{font-size:15px;font-weight:600}.p'
||'ad{padding:16px 18px}.meta{margin-top:8px}.meta-row{display:grid;grid-template-columns:1fr auto;margin-bottom:6px;font-size:9px}.kv{display:inline-flex;gap:18px}.kv span{display:inline-block;min-width:max(90px,15ch)}.right{justify-self:end}',
'table{width:100%;border-collapse:collapse}',
'th,td{border:1px solid var(--rule);padding:2px 2px;font-size:09px}',
'thead th{text-transform:none;font-size:10px;font-weight:bold}',
'thead tr:nth-child(1)th{background:#f3f3f3}',
'thead tr:nth-child(2)th{background:#f9f9f9}.center{text-align:center}.right-txt{text-align:right}',
'col.code{width:45px}',
'col.emp{width:150px}',
'col.desg{width:130px}',
'col.stat{width:50px}',
'col.in{width:55px}',
'col.out{width:55px}',
'col.late{width:30px}',
'col.early{width:30px}',
'col.loc-in{width:60px}',
'col.loc-out{width:60px}.summary{display:grid;grid-template-columns:1fr 1fr;gap:24px;width:300px;margin-top:8px}.summary table{width:100%}.summary td{padding:4px 6px;font-size:10px;font-weight:700}.summary td:first-child{width:70%}.muted{color:var(--m'
||'uted)}.no-border{border:none!important}.mt-8{margin-top:8px}.mt-12{margin-top:12px}',
'</style>',
'',
'',
'',
'<div class="page">',
'    <!-- Header -->',
'    <div class="report-header">',
'      <!-- Replace src with your actual logo path -->',
'      <img class="logo" src="http://10.30.25.8:9001/ords/hrm/r/103/files/static/v82/ipi.png" alt="IBN SINA Logo" />',
'      <div class="title">',
''');',
'',
'declare',
'  v_name varchar2(100);',
'BEGIN',
'  SELECT name INTO v_name ',
'   FROM company WHERE id = :G_COM_ID;',
'  htp.p(''<h1>''||v_name||''</h1>'' );',
'EXCEPTION',
'  WHEN NO_DATA_FOUND THEN',
'  null; -- htp.p(''<h1> The IBN SINA Pharmaceutical Industry PLC </h1>'');',
'END;',
'',
'declare ',
'',
'dept varchar2(100);',
'lo varchar2(100);',
'dat  varchar2(100);',
'sec varchar2(100);',
'begin ',
'SELECT distinct  ',
'       department, ',
'       jobloc,',
'       ATTDT       ',
'into dept, lo, dat',
'  FROM v_dept_attw',
' WHERE dept_id  = nvl(:P445_DEPARTMENT, 18)',
'AND attdate = :P445_DATE',
'and location_id = nvl(:P445_LOCATION, 0);',
'htp.p(''',
'        ',
'        <div class="subtitle">Daily Attendance Status</div>',
'      </div>',
'    </div>',
'',
'    <!-- Meta information -->',
'    <div class="meta">',
'      <div class="meta-row">',
'        <div class="kv">',
'          <div><strong>Date</strong>: ''||dat||''</div>',
'        </div>',
'        <div class="right"><strong>Print time</strong> : ''|| :print_time||''</div>',
'    </div>',
'    <div class="meta">',
'      <div class="meta-row">',
'        <div class="kv">',
'          <div><strong>Location</strong>: ''||lo||''</div>',
'        </div>      ',
'    </div>',
'      <div class="meta-row">',
'        <div class="kv">          ',
'          <div><strong>Department</strong>: ''||dept||''</div>',
'        </div>',
'        <div class="right"><strong>Section</strong> : ''||:P445_SECTION||''</div>',
'      </div>',
'    </div>'');',
'    exception ',
'    when no_data_found ',
'    then null;',
'    end;',
'',
'    htp.p(''<!-- Attendance table -->',
'    <table class="mt-8">',
'      <colgroup>',
'        <col class="code">',
'        <col class="emp">',
'        <col class="desg">',
'        <col class="stat">',
'        <col class="in">',
'        <col class="out">',
'        <col class="late">',
'        <col class="early">',
'        <col class="loc-in">',
'        <col class="loc-out">',
'      </colgroup>',
'      <thead>',
'        <tr>',
'          <th rowspan="2">Code</th>',
'          <th rowspan="2">Employee Name</th>',
'          <th rowspan="2">Designation</th>',
'          <th rowspan="2" class="center">Status</th>',
'          <th rowspan="2" class="center">IN<br/>Time</th>',
'          <th rowspan="2" class="center">OUT<br/>Time</th>',
'          <th rowspan="2" class="center">Late<br/>IN</th>',
'          <th rowspan="2" class="center">Early<br/>Out</th>',
'          <th colspan="2" class="center">Location</th>',
'        </tr>',
'        <tr>',
'          <th class="center">IN</th>',
'          <th class="center">OUT</th>',
'        </tr>',
'      </thead>',
'      <tbody>',
'        <!-- Rows reproduced to match the sample layout; edit values as needed -->',
'        '');',
'FOR x in  (SELECT aid,',
'       empid,',
'       empcode,',
'       fullname,',
'       dept_id,',
'       department,',
'       designation,',
'       desig_id,',
'       desig_sl,',
'       jobloc,',
'       attdate,',
'       attdt,',
'       weekd,',
'       office_start,',
'       office_end,',
'       shift_start,',
'       shift_end,',
'       status,',
'       in_time,',
'       out_time,',
'       punchin,',
'       punchout,',
'       late,',
'       early,',
'       in_id,',
'       inloc,',
'       out_id,',
'       outloc,',
'       total_h,',
'       notes,',
'       com_id,',
'       weekend,',
'       nextday,',
'       holiday',
'  FROM v_dept_attw',
' WHERE     dept_id  = :P445_DEPARTMENT',
'       AND attdate = :P445_DATE',
'       and location_id = :P445_LOCATION',
'       and emp_status = 1',
'      -- and com_id = :g_com_id',
'      order by GRADE asc, jdate asc, empcode asc',
') loop ',
'htp.p(''',
'        <tr>',
'          <td class="center">''||x.empcode||''</td>',
'          <td>''||x.fullname||''</td>',
'          <td>''||x.designation||''</td>',
'          <td class="center">''||x.status||''</td>',
'          <td class="center">''||x.punchin||''</td>',
'          <td class="center">''||x.punchout||''</td>',
'          <td class="center">''||x.late||''</td>',
'          <td class="center">''||x.early||''</td>',
'          <td>''||x.inloc||''</td>',
'          <td>''||x.outloc||''</td>',
'        </tr>''',
'',
'        );',
'            end loop;',
'            htp.p(''',
'      </tbody>',
'    </table>',
'',
'    <!-- Totals -->',
'',
'',
'    <div class="summary mt-12">',
'    '');',
'',
'    declare ',
'    tot number;',
'     totp number;',
'     tota number;',
'     totl number;',
'     tott number;',
'     totli number;',
'     toteo number;',
'',
'    begin',
' SELECT COUNT (*)                                     AS total,',
'       COUNT (CASE WHEN status = ''P'' THEN 1 END)     AS present_count,',
'       COUNT (CASE WHEN status = ''A'' THEN 1 END)     AS absent_count,',
'       COUNT (CASE WHEN status = ''L'' THEN 1 END)     AS leave_count,',
'       COUNT (CASE WHEN status = ''T'' THEN 1 END)     AS tour_count,',
'       COUNT (CASE WHEN late > 0 THEN 1 END)         AS late_count,',
'       COUNT (CASE WHEN early > 0 THEN 1 END)        AS early_count',
'',
'       into tot, totp, tota, totl, tott, totli, toteo',
'  FROM v_dept_attw',
' WHERE     dept_id = :p445_department',
'       AND attdate = :p445_date',
'       AND location_id = :p445_location;',
'',
'    htp.p(''',
'      <table>',
'        <tr><td>Total Present:</td><td class="right-txt">''||totp||''</td></tr>',
'        <tr><td>Total LateIn:</td><td class="right-txt">''||totli||''</td></tr>',
'        <tr><td>Total EarlyOut:</td><td class="right-txt">''||toteo||''</td></tr>',
'      </table>',
'      <table>',
'        <tr><td>Total Absent:</td><td class="right-txt">''||tota||''</td></tr>',
'        <tr><td>Total Tour:</td><td class="right-txt">''||tott||''</td></tr>',
'        <tr><td>Total Leave:</td><td class="right-txt">''||totl||''</td></tr>',
'      </table>',
'    </div>',
'    </div>',
'  </div>'');',
'  end;',
'',
''))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
);
