'  )',
'loop',
' htp.p(''  <tbody>',
'          <tr><td>''||x.adate||''</td><td>''||x.aday||''</td><td>''||x.starttime||''</td><td>''||x.endtime||''</td><td>''||null||''</td><td>''||x.rema||''</td></tr>',
'          </tbody>'');',
'end loop;',
