'      --title: #000;',
'    }',
'    .page {',
'      width: 940px; /* close to A4 @ ~96dpi */',
'      margin: 0 auto;           ',
'      }      ',
'',
'      /* Header */',
'.report-header {',
'  display: flex;',
'  align-items: center;',
'  justify-content: center; /* centers the text container */',
'  gap: 12px;',
