'        <div><span class="label"> Department: </span>'');',
'declare ',
'vDept varchar2(100);',
'begin',
'select dept_name  into vDept',
'from departments',
'where id = :P447_DEPARTMENT;',
'',
'  htp.p(''<span>''||vDept||''</span></div>'');',
'  ',
'  end; ',
'  htp.p('' </div>',
'     ',
'      <thead>        ',
'        <tr class="colhead">',
'          <th>Employee<br>code</th>',
'          <th>Employee Name</th>',
'          <th>Designation</th>',
'          <th class="mini"><span class="abbr">SL</span><span class="sub">Days</span></th>',
'          <th class="mini"><span class="abbr">CL</span><span class="sub">Days</span></th>',
'          <th class="mini"><span class="abbr">EL</span><span class="sub">Days</span></th>',
'          <th class="mini"><span class="abbr">Total</span><span class="sub">Leave</span></th>',
'          <th class="mini"><span class="abbr">EL</span><span class="sub">Encash</span></th>',
'        </tr>',
'      </thead>'');',
'',
'for x in (select vl.empid,',
'       ipi,',
'       fullname,',
'       department,',
'       designation,',
'       dept_id,',
'       vl.yearmn,',
'       vl.sl_days,',
'       vl.cl_days,',
'       vl.el_days,',
'       vl.total_leave,',
'       vl.el_encash',
'  from v_emp_leave_total vl, v_emp v',
' where vl.empid = v.emp_id',
' and dept_id = :P447_DEPARTMENT',
' and yearmn = :P447_YEARMN',
