wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(42604728184635503)
,p_event_id=>wwv_flow_api.id(42604669522635502)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_SET_VALUE'
,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P453_FROM_DATE'
,p_attribute_01=>'FUNCTION_BODY'
,p_attribute_06=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_cnt   NUMBER;',
'    v_redt   DATE;',
'BEGIN',
'    SELECT COUNT (*) cnt',
'      INTO v_cnt',
'      FROM t_post_trans_history',
'     WHERE emp_id = :P453_EMP_ID;',
'',
'    IF v_cnt <= 0',
'    THEN',
'        SELECT join_date  ',
'          INTO v_redt',
'          FROM employees',
'         WHERE id = :P453_EMP_ID;',
'    ELSE',
'        SELECT MAX(TO_DATE(TO_CHAR(effective_date, ''MM/DD/YYYY''), ''MM/DD/YYYY''))',
'          INTO v_redt',
'          FROM t_post_trans_history',
'         WHERE emp_id = :P453_EMP_ID;',
'    END IF;',
'',
'    return  TO_CHAR(v_redt, ''DD/MON/YYYY'') ;',
'END;'))
,p_attribute_07=>'P453_EMP_ID'
,p_attribute_08=>'N'
,p_attribute_09=>'N'
,p_wait_for_result=>'Y'
);
