'    l_user_id NUMBER;',
'BEGIN',
'    -- Get the currently logged-in user ID',
'    l_user_id := :user_id;',
'',
'    IF :P991_PID IS NOT NULL THEN',
'        -- Update',
'        UPDATE T_MENU',
'        SET upd_by = l_user_id,',
