wwv_flow_api.create_page_validation(
 p_id=>wwv_flow_api.id(5312205839519901)
,p_validation_name=>'Password Validate'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'V_PASS VARCHAR2(100);',
'BEGIN',
'SELECT passw',
'INTO V_PASS',
'  FROM employees',
' WHERE     upper(emp_id) = upper(:P9999_USERNAME)     ',
'       AND STATUS = 1;',
'IF V_PASS = :P9999_PASSWORD THEN',
'RETURN TRUE;',
'ELSE ',
'RETURN FALSE;',
'END IF;',
'exception ',
'when no_data_found',
'then  ',
'return false;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Username or Password Incorrect !!!'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(5239966653024401)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Username Cookie'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'apex_authentication.send_login_username_cookie (',
'    p_username => lower(:P9999_USERNAME),',
'    p_consent  => :P9999_REMEMBER = ''Y'' );'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(5239520129024401)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Login'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'apex_authentication.login(',
'    p_username => :P9999_USERNAME,',
'    p_password => :P9999_PASSWORD );',
'DECLARE',
'    V_CHK       NUMBER;',
'    V_SESSION   NUMBER;',
'    V_SID       NUMBER;',
'    V_SERIAL    NUMBER;',
'    V_LOGIN     NUMBER;',
'    V_MACHINE   VARCHAR2 (100);',
'    V_RPT_URL   VARCHAR2 (100);',
'    V_DIR       VARCHAR2 (100);',
'    v_com       NUMBER;',
'BEGIN',
'    SELECT COUNT (*)',
'      INTO V_CHK',
'      FROM employees',
'     WHERE lower(emp_id) = lower( :P9999_USERNAME) AND status = 1;',
'',
'    BEGIN',
'        SELECT emp_id,',
'               USER_GRP,',
'            --    com_id,',
'            --    com_id,',
'               id',
'          INTO :g_uname,',
'               :g_user_grp,',
'            --    :G_COM_ID,',
'            --    v_com,',
'               :user_id',
'          FROM employees',
'         WHERE lower (emp_id) = lower ( :P9999_USERNAME);',
'',
'       ',
'',
'     SELECT  ID,',
'               ID',
'               INTO  :G_COM_ID,',
'               v_com',
'     FROM COMPANY',
'     WHERE ID = :P9999_COMPANY;',
'',
'     SELECT CODE INTO :G_COM_CODE',
'       FROM COMPANY',
'       WHERE ID = v_com;',
'',
'',
'    EXCEPTION',
'        WHEN OTHERS',
'        THEN',
'            :G_COM_ID := 1;',
'            :G_COM_CODE	:= ''IPI'';',
'            :user_id := 1;',
'    END;',
'-- EXCEPTION',
'--  WHEN OTHERS THEN NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(5240710490024401)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_SESSION_STATE'
,p_process_name=>'Clear Page(s) Cache'
